#!/usr/bin/env node
/**
 * Sinh route.js mỏng cho toàn bộ endpoint chính trong registry.
 *
 * - Nguồn sự thật: src/shared/api-endpoints.js (bỏ endpoint aliasOf).
 * - Mỗi file route chỉ gọi withApi + handler/schema của module tương ứng.
 * - Idempotent: nội dung không đổi thì không ghi; file thủ công (không có marker
 *   "@generated") sẽ không bị ghi đè.
 *
 * Chạy: npm run gen:routes
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { PRIMARY_API_ENDPOINTS } from '../src/shared/api-endpoints.js';
import { MODULES } from '../src/shared/constants/modules.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GENERATED_MARKER = '@generated by scripts/gen-routes.js';
const METHOD_ORDER = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'];

function moduleFolder(moduleCode) {
  const folder = MODULES[moduleCode]?.folder;
  if (!folder) throw new Error(`Không tìm thấy folder cho module ${moduleCode}`);
  return folder;
}

function routeFileFor(apiPath) {
  const segments = apiPath.split('/').filter(Boolean);
  return path.join(ROOT, 'src', 'app', ...segments, 'route.js');
}

function sortMethods(entries) {
  return [...entries].sort(
    (a, b) => METHOD_ORDER.indexOf(a.method) - METHOD_ORDER.indexOf(b.method),
  );
}

function renderRoute(apiPath, entries) {
  const modules = new Set(entries.map((entry) => entry.module));
  if (modules.size !== 1) {
    throw new Error(
      `Một route.js chỉ được thuộc một module: ${apiPath} (${[...modules].join(', ')})`,
    );
  }
  const moduleCode = entries[0].module;
  const folder = moduleFolder(moduleCode);
  const sorted = sortMethods(entries);
  const codes = sorted.map((entry) => entry.code);
  const title = sorted.map((entry) => `${entry.code} — ${entry.name}`).join(' | ');

  const lines = [
    "import 'server-only';",
    `// ${GENERATED_MARKER}`,
    `// Endpoint: ${title}`,
    `// Path: ${apiPath}`,
    '// Tạo lại bằng `npm run gen:routes`; không sửa tay.',
    "import { withApi } from '@/server/http/withApi.js';",
    `import { handlers } from '@/modules/${folder}/server/handlers.js';`,
    `import { validationSchemas } from '@/modules/${folder}/server/validation.js';`,
    '',
    "export const runtime = 'nodejs';",
    "export const dynamic = 'force-dynamic';",
    '',
  ];

  for (const entry of sorted) {
    const schema = `validationSchemas['${entry.code}']`;
    lines.push(
      `export const ${entry.method} = withApi('${entry.code}', handlers['${entry.code}'], {`,
      `  schemas: ${schema},`,
      '});',
      '',
    );
  }

  return { content: lines.join('\n'), codes, moduleCode };
}

async function writeRoute(apiPath, content) {
  const filePath = routeFileFor(apiPath);
  const displayPath = path.relative(ROOT, filePath).split(path.sep).join('/');

  try {
    const existing = await readFile(filePath, 'utf8');
    if (existing === content) return { status: 'unchanged', displayPath };
    if (!existing.includes(GENERATED_MARKER)) {
      return { status: 'manual', displayPath };
    }
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }

  await mkdir(path.dirname(filePath), { recursive: true });
  await writeFile(filePath, content, 'utf8');
  return { status: 'written', displayPath };
}

async function main() {
  const groups = new Map();
  for (const endpoint of PRIMARY_API_ENDPOINTS) {
    if (endpoint.aliasOf) continue;
    if (!groups.has(endpoint.path)) groups.set(endpoint.path, []);
    groups.get(endpoint.path).push(endpoint);
  }

  const counters = { written: 0, unchanged: 0, manual: 0 };
  for (const apiPath of [...groups.keys()].sort()) {
    const { content } = renderRoute(apiPath, groups.get(apiPath));
    const result = await writeRoute(apiPath, content);
    counters[result.status] += 1;
    if (result.status === 'written') console.info(`  + ${result.displayPath}`);
    if (result.status === 'manual') {
      console.warn(`  ! Bỏ qua file thủ công: ${result.displayPath}`);
    }
  }

  console.info(
    `gen:routes — ${groups.size} route (${PRIMARY_API_ENDPOINTS.length} endpoint chính): ` +
      `${counters.written} ghi mới/cập nhật, ${counters.unchanged} không đổi, ${counters.manual} bỏ qua.`,
  );
}

main().catch((error) => {
  console.error('gen:routes thất bại:', error);
  process.exitCode = 1;
});
